  "/sw.js","/manifest.webmanifest","/icon.svg","/style.css","/app.js","/tv-hls.js",
  "/nm-foundation.js","/nm-foundation.css","/nm-home.js","/nm-home.css",
  "/.well-known/assetlinks.json"
