let cached: { expiresAt: number; payload: NocFuelPayload } | null = null;

function normalizeHtml(html: string) {
  return html
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;|&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&#8226;|&bull;/gi, "•")
    .replace(/\s+/g, " ")
    .trim();
}

function parseNumber(value: string | undefined): number | null {
  if (!value) return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
}

function extract(block: string, pattern: RegExp): number | null {
  return parseNumber(pattern.exec(block)?.[1]);
}

export function parseNocFuelPage(html: string): NocFuelZone[] {
  const text = normalizeHtml(html);
  const marker = text.toLowerCase().indexOf("current retail selling price");
  const scope = marker >= 0 ? text.slice(marker, marker + 12_000) : text.slice(0, 12_000);
  const starts = [...scope.matchAll(/\(([^()]*,[^()]*)\)\s*Petrol\s*\(MS\)/gi)];
  const zones: NocFuelZone[] = [];

  for (let i = 0; i < starts.length; i++) {
    const match = starts[i];
    const start = match.index ?? 0;
    const end = i + 1 < starts.length ? (starts[i + 1].index ?? start + 2200) : Math.min(scope.length, start + 2200);
    const block = scope.slice(start, end);
    const petrol = extract(block, /Petrol\s*\(MS\)[^\d]{0,60}([\d.]+)/i);
    const diesel = extract(block, /Diesel\s*\(HSD\)[^\d]{0,60}([\d.]+)/i);
    const kerosene = extract(block, /Kerosene\s*\(SKO\)[^\d]{0,60}([\d.]+)/i);
    if (petrol == null || diesel == null || kerosene == null) continue;
    zones.push({
      depots: match[1].split(",").map((value) => value.trim()).filter(Boolean),
      petrol, diesel, kerosene,
      atfDutyFreeUsdPerKl: extract(block, /Aviation Fuel Duty Free[^\d]{0,80}([\d.]+)/i),
      atfDomesticNprPerL: extract(block, /Aviation Turbine Fuel\s*\(Jet A-1\)[^\d]{0,80}([\d.]+)/i),
      lpgNprPerCylinder: extract(block, /LP Gas[^\d]{0,60}([\d.]+)/i),
    });
  }
  return zones;
}

function snapshot(note?: string): NocFuelPayload {
  return {
    ...OFFICIAL_SNAPSHOT,
    fetchedAt: new Date().toISOString(),
    note: note || OFFICIAL_SNAPSHOT.note,
    zones: OFFICIAL_SNAPSHOT.zones.map((zone) => ({ ...zone, depots: [...zone.depots] })),
  };
}

export async function fetchNocFuelPrices(): Promise<NocFuelPayload> {
  const now = Date.now();
  if (cached && cached.expiresAt > now) return cached.payload;

  try {
    const response = await fetch(NOC_URL, {
      headers: {
        accept: "text/html,application/xhtml+xml",
        "user-agent": "Patro-Nepali-Utility/1.0 (+https://patro-blush.vercel.app)"
      },
      redirect: "follow",
      signal: AbortSignal.timeout(8000),
    });
    if (!response.ok) throw new Error("noc_http_" + response.status);
    const declared = Number(response.headers.get("content-length") || "0");
    if (Number.isFinite(declared) && declared > MAX_HTML_BYTES) throw new Error("noc_response_too_large");
    const html = await response.text();
    if (new TextEncoder().encode(html).byteLength > MAX_HTML_BYTES) throw new Error("noc_response_too_large");

    const zones = parseNocFuelPage(html);
    const normalized = normalizeHtml(html).toLowerCase();
    const maintenance = normalized.includes("coming soon") || normalized.includes("website") && normalized.includes("rebuilt");
    const result: NocFuelPayload = zones.length
      ? {
          ok: true, source: "Nepal Oil Corporation", sourceUrl: NOC_URL,
          fetchedAt: new Date().toISOString(), effectiveDate: null,
          freshness: "live", stale: false, zones
        }
      : snapshot(maintenance
          ? "NOC is currently serving its website maintenance page to the server runtime. Showing the latest source-verified NOC regional snapshot."
          : "NOC's live page format could not be parsed. Showing the latest source-verified NOC regional snapshot.");

    cached = { expiresAt: now + CACHE_TTL_MS, payload: result };
    return result;
  } catch (error) {
    const result = snapshot("Live NOC retrieval failed (" + String((error as Error)?.message || error) + "). Showing the latest source-verified NOC regional snapshot.");
    cached = { expiresAt: now + 2 * 60 * 1000, payload: result };
    return result;
  }
}

const TE = new TextEncoder();
const TD = new TextDecoder();

const RADIO_BROWSER_SERVERS = [
  "https://de1.api.radio-browser.info",
  "https://de2.api.radio-browser.info",
  "https://fi1.api.radio-browser.info"
];

const MAX_REDIRECTS = 6;
const MAX_MANIFEST_BYTES = 1_048_576;
const COUNTRY_CACHE_MS = 15 * 60_000;

let HMAC_KEY: CryptoKey | null = null;
let COUNTRY_CACHE: { at: number; rows: Array<{ code: string; name: string; count: number }> } | null = null;

type RadioBrowserStation = {
  stationuuid?: string;
  name?: string;
  url?: string;
  url_resolved?: string;
  homepage?: string;
  favicon?: string;
  tags?: string;
  countrycode?: string;
  state?: string;
  language?: string;
  languagecodes?: string;
  codec?: string;
  bitrate?: number;
  hls?: number | boolean;
  votes?: number;
  clickcount?: number;
  lastcheckok?: number | boolean;
  lastchecktime_iso8601?: string;
};

function text(value: unknown, max = 240) {
  return String(value ?? "").replace(/[\u0000-\u001F\u007F]/g, "").trim().slice(0, max);
}

function privateHost(raw: string) {
  const h = raw.toLowerCase().replace(/^\[|\]$/g, "");
  if (
    h === "localhost" ||
    h.endsWith(".localhost") ||
    h.endsWith(".local") ||
    h.endsWith(".internal") ||
    h === "metadata.google.internal"
  ) return true;

  if (h.includes(":")) {
    return h === "::1" || h.startsWith("fc") || h.startsWith("fd") ||
      h.startsWith("fe8") || h.startsWith("fe9") || h.startsWith("fea") || h.startsWith("feb");
  }

  const a = h.split(".").map(Number);
  if (a.length === 4 && a.every((x) => Number.isInteger(x) && x >= 0 && x <= 255)) {
    const [x, y] = a;
    return x === 0 || x === 10 || x === 127 ||
      (x === 100 && y >= 64 && y <= 127) ||
      (x === 169 && y === 254) ||
      (x === 172 && y >= 16 && y <= 31) ||
      (x === 192 && y === 168) ||
      (x === 198 && (y === 18 || y === 19)) ||
      x >= 224;
  }
  return false;
}

function safeUrl(raw: string, base?: string) {
  let url: URL;
  try {
    url = new URL(raw, base);
  } catch {
    throw new Error("invalid_radio_stream_url");
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") throw new Error("unsupported_radio_protocol");
  if (url.username || url.password) throw new Error("credentials_not_allowed");
  if (privateHost(url.hostname)) throw new Error("radio_stream_target_blocked");
  return url;
}

function b64u(bytes: Uint8Array) {
  let s = "";
  for (let i = 0; i < bytes.length; i += 8192) s += String.fromCharCode(...bytes.subarray(i, i + 8192));
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function unb64u(value: string) {
  const padded = value.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((value.length + 3) % 4);
  const bin = atob(padded);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function hmacKey() {
  if (HMAC_KEY) return HMAC_KEY;
  const secret =
    Deno.env.get("RADIO_RELAY_SECRET") ||
    Deno.env.get("TV_RELAY_SECRET") ||
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ||
    "";
  if (!secret) throw new Error("radio_relay_secret_unavailable");
  HMAC_KEY = await crypto.subtle.importKey(
    "raw",
    TE.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"]
  );
  return HMAC_KEY;
}

async function sign(value: string) {
  const bytes = new Uint8Array(await crypto.subtle.sign("HMAC", await hmacKey(), TE.encode(value)));
  return b64u(bytes);
}

async function verify(value: string, signature: string) {
  try {
    return await crypto.subtle.verify("HMAC", await hmacKey(), unb64u(signature), TE.encode(value));
  } catch {
    return false;
  }
}

async function signedStreamPath(raw: string) {
  const target = safeUrl(raw).toString();
  const packed = b64u(TE.encode(target));
  const signature = await sign(packed);
  return "/api/v1/radio/stream?u=" + encodeURIComponent(packed) + "&s=" + encodeURIComponent(signature);
}

function regionName(code: string) {
  try {
    return new Intl.DisplayNames(["en"], { type: "region" }).of(code) || code;
  } catch {
    return code;
  }
}

async function rbFetch(path: string) {
  let lastError: unknown = null;
  const offset = Math.floor(Date.now() / 60_000) % RADIO_BROWSER_SERVERS.length;
  for (let i = 0; i < RADIO_BROWSER_SERVERS.length; i++) {
    const base = RADIO_BROWSER_SERVERS[(i + offset) % RADIO_BROWSER_SERVERS.length];
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8_000);
    try {
      const response = await fetch(base + path, {
        headers: {
          accept: "application/json",
          "user-agent": "NepaliPatro/2.1 (+https://patro-blush.vercel.app)"
        },
        signal: controller.signal
      });
      if (!response.ok) throw new Error("radio_browser_" + response.status);
      return await response.json();
    } catch (error) {
      lastError = error;
    } finally {
      clearTimeout(timer);
    }
  }
  throw lastError || new Error("radio_browser_unavailable");
}

async function countryFacets() {
  const now = Date.now();
  if (COUNTRY_CACHE && now - COUNTRY_CACHE.at < COUNTRY_CACHE_MS) return COUNTRY_CACHE.rows;
  const raw = await rbFetch("/json/countrycodes?hidebroken=true&order=stationcount&reverse=true&limit=300");
  const rows = (Array.isArray(raw) ? raw : [])
    .map((row: any) => {
      const code = text(row?.name, 2).toUpperCase();
      const count = Math.max(0, Number(row?.stationcount) || 0);
      return { code, name: regionName(code), count };
    })
    .filter((row: any) => /^[A-Z]{2}$/.test(row.code) && row.count > 0);
  COUNTRY_CACHE = { at: now, rows };
  return rows;
}

async function localNepalStations() {
  const supabaseUrl = Deno.env.get("SUPABASE_URL") || "";
  const serviceRole = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
  if (!supabaseUrl || !serviceRole) return [];

  const select = [
    "slug","name_ne","name_en","frequency_mhz","district_id","city","languages",
    "website","logo_url","stream_format","stream_status","stream_url","category","last_ok_at"
  ].join(",");
  const url = supabaseUrl + "/rest/v1/fm_stations?select=" + encodeURIComponent(select) +
    "&stream_status=eq.verified&stream_url=not.is.null&limit=500";

  try {
    const response = await fetch(url, {
      headers: {
        apikey: serviceRole,
        authorization: "Bearer " + serviceRole,
        accept: "application/json"
      },
      signal: AbortSignal.timeout(4_000)
    });
    if (!response.ok) return [];
    const rows = await response.json();
    return Array.isArray(rows) ? rows : [];
  } catch {
    return [];
  }
}

function dedupeKey(name: string, url: string) {
  let host = "";
  try { host = new URL(url).hostname.replace(/^www\./, ""); } catch {}
  return name.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu, "") + "|" + host;
}

async function browserItem(row: RadioBrowserStation) {
  const source = text(row.url_resolved || row.url, 2048);
