  if (!(row.lastcheckok === true || Number(row.lastcheckok) === 1)) return null;

  const code = text(row.countrycode, 2).toUpperCase();
  const languages = text(row.language, 300).split(",").map((x) => x.trim()).filter(Boolean).slice(0, 6);
